// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const { body, query, validationResult } = require('express-validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// ===========================
// SECURITY MIDDLEWARE
// ===========================

// 1. Security Headers - Protect against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));

// 2. CORS Configuration - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for specific endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.',
});

// 4. Body Parsing with Size Limits - Prevent payload attacks
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Logging - Monitor for suspicious activity
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined')); // Use 'combined' format for production
}

// 6. Disable X-Powered-By header - Don't advertise technology stack
app.disable('x-powered-by');

// ===========================
// HELPER FUNCTIONS
// ===========================

// Sanitize output to prevent information leakage
const sanitizeError = (error) => {
  if (process.env.NODE_ENV === 'production') {
    return {
      status: 'error',
      message: 'An error occurred processing your request',
    };
  }
  return {
    status: 'error',
    message: error.message,
    stack: error.stack,
  };
};

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'error',
      message: 'Validation failed',
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// ===========================
// ROUTES
// ===========================

// Health check endpoint - minimal information disclosure
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Users endpoint with input validation and pagination
app.get('/users',
  [
    // Input validation
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be an integer between 1 and 1000'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be an integer between 1 and 100'),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isLength({ max: 100 })
      .withMessage('Search query too long'),
    handleValidationErrors
  ],
  strictLimiter, // Apply strict rate limiting
  (req, res, next) => {
    try {
      // Parse validated query parameters
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const search = req.query.search || '';

      // Mock data - In production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter based on search (if provided)
      let filteredUsers = allUsers;
      if (search) {
        filteredUsers = allUsers.filter(user =>
          user.name.toLowerCase().includes(search.toLowerCase()) ||
          user.email.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        status: 'success',
        data: {
          users: paginatedUsers,
          pagination: {
            page,
            limit,
            total: filteredUsers.length,
            totalPages: Math.ceil(filteredUsers.length / limit)
          }
        }
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

// Example: POST endpoint with validation
app.post('/users',
  [
    // Input validation
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 100 })
      .withMessage('Email too long'),
    handleValidationErrors
  ],
  strictLimiter,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // In production, save to database with parameterized queries
      // to prevent SQL injection
      const newUser = {
        id: Date.now(), // In production, use proper ID generation
        name,
        email,
        createdAt: new Date().toISOString()
      };

      res.status(201).json({
        status: 'success',
        data: { user: newUser }
      });
    } catch (error) {
      next(error);
    }
  }
);

// ===========================
// ERROR HANDLING
// ===========================

// 404 Handler - Must be after all routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Resource not found',
    path: req.path
  });
});

// Global Error Handler - Must be last
app.use((err, req, res, next) => {
  // Log error details for debugging (use proper logging service in production)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send appropriate error response
  res.status(statusCode).json(sanitizeError(err));
});

// ===========================
// GRACEFUL SHUTDOWN
// ===========================

const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

# Security Review Report for app.js

## Executive Summary
The current `app.js` implementation lacks essential security controls and error handling mechanisms. This review identifies critical vulnerabilities and provides recommendations to improve the application's security posture.

---

## Critical Issues Found

### 1. **No Input Validation** 🔴 CRITICAL
**Issue:** User inputs are not validated or sanitized, exposing the application to various injection attacks.

**Risk:**
- Cross-Site Scripting (XSS)
- SQL Injection (if database is added)
- Command Injection
- Path Traversal

**Recommendation:**
```javascript
// Use express-validator for input validation
const { body, query, validationResult } = require('express-validator');

app.get('/users',
  query('search').optional().trim().escape().isLength({ max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Handle request
  }
);
```

### 2. **Missing Security Headers** 🔴 CRITICAL
**Issue:** No security headers are set, making the app vulnerable to:
- Clickjacking
- MIME-type sniffing
- XSS attacks

**Recommendation:**
```bash
npm install helmet
```
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 3. **No Rate Limiting** 🟠 HIGH
**Issue:** Application is vulnerable to brute force attacks and DoS.

**Recommendation:**
```bash
npm install express-rate-limit
```
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);
```

### 4. **No Error Handling Middleware** 🟠 HIGH
**Issue:** Unhandled errors could crash the application or leak sensitive information.

**Recommendation:**
```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});
```

### 5. **Missing CORS Configuration** 🟠 HIGH
**Issue:** No CORS policy defined, potentially allowing unauthorized cross-origin requests.

**Recommendation:**
```bash
npm install cors
```
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));
```

### 6. **No Request Body Size Limits** 🟡 MEDIUM
**Issue:** Large payloads could cause memory exhaustion (DoS).

**Recommendation:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 7. **Information Disclosure** 🟡 MEDIUM
**Issue:** Express advertises itself via X-Powered-By header.

**Recommendation:**
```javascript
app.disable('x-powered-by');
```

### 8. **No Logging/Monitoring** 🟡 MEDIUM
**Issue:** No audit trail for security incidents or debugging.

**Recommendation:**
```bash
npm install morgan
```
```javascript
const morgan = require('morgan');
app.use(morgan('combined'));
```

### 9. **No Authentication/Authorization** 🟡 MEDIUM
**Issue:** Endpoints are publicly accessible without authentication.

**Recommendation:**
```bash
npm install jsonwebtoken
```
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access denied' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // Protected route
});
```

### 10. **No Graceful Shutdown** 🟡 MEDIUM
**Issue:** Server doesn't handle shutdown signals properly.

**Recommendation:**
```javascript
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

---

## Additional Security Best Practices

### 1. **Environment Variables**
Never hardcode sensitive data:
```javascript
// Use dotenv for configuration
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const DB_CONNECTION = process.env.DATABASE_URL;
```

### 2. **Content Security Policy**
Implement strict CSP headers:
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));
```

### 3. **HTTPS Enforcement**
Force HTTPS in production:
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 4. **Parameterized Queries**
When adding database functionality, always use parameterized queries:
```javascript
// Good - Parameterized query
const result = await db.query(
  'SELECT * FROM users WHERE id = $1',
  [userId]
);

// Bad - String concatenation (SQL Injection risk)
const result = await db.query(
  `SELECT * FROM users WHERE id = ${userId}`
);
```

### 5. **Dependency Security**
Regularly audit dependencies:
```bash
npm audit
npm audit fix
```

---

## Implementation Priority

### Immediate (Do Now)
1. ✅ Add helmet for security headers
2. ✅ Implement rate limiting
3. ✅ Add error handling middleware
4. ✅ Implement input validation
5. ✅ Add request body size limits

### Short-term (This Week)
6. ✅ Configure CORS properly
7. ✅ Add logging/monitoring
8. ✅ Disable X-Powered-By header
9. ✅ Implement graceful shutdown
10. ⬜ Set up environment variables

### Medium-term (This Month)
11. ⬜ Implement authentication/authorization
12. ⬜ Add HTTPS enforcement
13. ⬜ Set up security monitoring and alerts
14. ⬜ Implement API versioning
15. ⬜ Add comprehensive unit tests

---

## Package Dependencies

Install these packages to implement security improvements:
```bash
npm install helmet express-rate-limit cors express-validator morgan dotenv
npm install jsonwebtoken bcrypt  # For authentication
npm install --save-dev jest supertest  # For testing
```

---

## Testing Security Improvements

Create security tests:
```javascript
// security.test.js
const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {
  test('Should set security headers', async () => {
    const response = await request(app).get('/health');
    expect(response.headers['x-frame-options']).toBeDefined();
    expect(response.headers['x-content-type-options']).toBeDefined();
  });

  test('Should reject invalid input', async () => {
    const response = await request(app)
      .get('/users?page=invalid');
    expect(response.status).toBe(400);
  });

  test('Should rate limit requests', async () => {
    // Make multiple requests to trigger rate limit
    for (let i = 0; i < 101; i++) {
      await request(app).get('/health');
    }
    const response = await request(app).get('/health');
    expect(response.status).toBe(429);
  });
});
```

---

## Monitoring and Maintenance

1. **Regular Security Audits**: Run `npm audit` weekly
2. **Dependency Updates**: Update dependencies monthly
3. **Log Review**: Monitor logs for suspicious activity
4. **Performance Monitoring**: Track response times and error rates
5. **Penetration Testing**: Conduct annual security assessments

---

## Conclusion

The current implementation requires significant security enhancements. The improved version (`app.improved.js`) addresses all critical issues and implements industry-standard security practices. Prioritize implementing the "Immediate" actions to establish a baseline security posture.

**Security Score:**
- Current: 2/10 ⚠️
- With Improvements: 8/10 ✅

---

## Resources

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Checklist](https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [express-validator Documentation](https://express-validator.github.io/)

