// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Logging
const cors = require('cors'); // CORS configuration

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers - Protect against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Body Parsing with Size Limits
app.use(express.json({ 
  limit: '10kb',
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf);
    } catch (e) {
      throw new Error('Invalid JSON');
    }
  }
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 4. Rate Limiting - Prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  skip: (req) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  }
});
app.use(limiter);

// 5. Logging - Track requests for security monitoring
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined', {
    skip: (req) => req.path === '/health' // Skip logging health checks
  }));
}

// 6. Disable unnecessary headers
app.disable('x-powered-by');

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Sanitize and validate query parameters
 */
const validateQueryParams = (req, res, next) => {
  const errors = [];

  // Validate page parameter if present
  if (req.query.page) {
    const page = parseInt(req.query.page, 10);
    if (isNaN(page) || page < 1 || page > 1000) {
      errors.push('Invalid page parameter. Must be between 1 and 1000.');
    }
  }

  // Validate limit parameter if present
  if (req.query.limit) {
    const limit = parseInt(req.query.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('Invalid limit parameter. Must be between 1 and 100.');
    }
  }

  // Validate search parameter if present (prevent XSS and SQL injection)
  if (req.query.search) {
    const search = req.query.search.trim();
    if (search.length > 100) {
      errors.push('Search query too long. Maximum 100 characters.');
    }
    // Remove potentially dangerous characters
    req.query.search = validator.escape(search);
  }

  // Validate email parameter if present
  if (req.query.email && !validator.isEmail(req.query.email)) {
    errors.push('Invalid email format.');
  }

  // Validate ID parameter if present
  if (req.query.id) {
    const id = parseInt(req.query.id, 10);
    if (isNaN(id) || id < 1) {
      errors.push('Invalid ID parameter. Must be a positive integer.');
    }
  }

  if (errors.length > 0) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors
    });
  }

  next();
};

/**
 * Validate path parameters
 */
const validateIdParam = (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1 || id > Number.MAX_SAFE_INTEGER) {
    return res.status(400).json({
      error: 'Invalid ID parameter',
      message: 'ID must be a valid positive integer'
    });
  }

  req.params.id = id; // Store validated integer
  next();
};

// ============================================================================
// ERROR HANDLING HELPERS
// ============================================================================

/**
 * Async error wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Custom error class for application errors
 */
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No authentication required for monitoring
 */
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Get all users with pagination and filtering
 * In production, this should require authentication
 */
app.get('/users', validateQueryParams, asyncHandler(async (req, res) => {
  try {
    // In a real application, this would query a database
    // and should include authentication/authorization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if requested
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    // Filter by search query if provided
    let filteredUsers = paginatedUsers;
    if (req.query.search) {
      const search = req.query.search.toLowerCase();
      filteredUsers = paginatedUsers.filter(user => 
        user.name.toLowerCase().includes(search) || 
        user.email.toLowerCase().includes(search)
      );
    }

    res.status(200).json({
      success: true,
      data: filteredUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    throw new AppError('Failed to retrieve users', 500);
  }
}));

/**
 * Get user by ID
 * Demonstrates parameter validation
 */
app.get('/users/:id', validateIdParam, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // In a real application, query the database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    throw new AppError('User not found', 404);
  }

  res.status(200).json({
    success: true,
    data: user
  });
}));

/**
 * Create new user
 * Demonstrates POST input validation
 */
app.post('/users', asyncHandler(async (req, res) => {
  const { name, email } = req.body;

  // Validate required fields
  const errors = [];

  if (!name || typeof name !== 'string') {
    errors.push('Name is required and must be a string');
  } else if (name.trim().length < 2 || name.trim().length > 50) {
    errors.push('Name must be between 2 and 50 characters');
  } else if (!/^[a-zA-Z\s'-]+$/.test(name)) {
    errors.push('Name contains invalid characters');
  }

  if (!email || typeof email !== 'string') {
    errors.push('Email is required and must be a string');
  } else if (!validator.isEmail(email)) {
    errors.push('Invalid email format');
  }

  if (errors.length > 0) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors
    });
  }

  // Sanitize inputs
  const sanitizedName = validator.escape(name.trim());
  const sanitizedEmail = validator.normalizeEmail(email.trim());

  // In a real application, save to database
  const newUser = {
    id: Date.now(), // In production, use proper ID generation
    name: sanitizedName,
    email: sanitizedEmail,
    createdAt: new Date().toISOString()
  };

  res.status(201).json({
    success: true,
    data: newUser
  });
}));

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Handle 404 - Route not found
 */
app.use((req, res, next) => {
  const error = new AppError(
    `Cannot ${req.method} ${req.path}`,
    404
  );
  next(error);
});

/**
 * Global error handler
 * Must be defined last, after all other middleware and routes
 */
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  if (process.env.NODE_ENV !== 'test') {
    console.error('Error:', {
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
      timestamp: new Date().toISOString(),
      path: req.path,
      method: req.method
    });
  }

  // Default error values
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production' && !err.isOperational) {
    message = 'Something went wrong';
  }

  // Handle specific error types
  if (err.name === 'ValidationError') {
    statusCode = 400;
    message = 'Validation Error';
  }

  if (err.name === 'UnauthorizedError') {
    statusCode = 401;
    message = 'Unauthorized';
  }

  if (err.type === 'entity.parse.failed') {
    statusCode = 400;
    message = 'Invalid JSON payload';
  }

  // Send error response
  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && {
      stack: err.stack,
      details: err.details
    })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Only start server if not in test mode
if (process.env.NODE_ENV !== 'test') {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

