  } else {
    console.log('\n✅ All security tests passed!');
  }

  process.exit(failed > 0 ? 1 : 0);
};

// Run tests if executed directly
if (require.main === module) {
  runTests().catch(error => {
    console.error('Test suite error:', error);
    process.exit(1);
  });
}

module.exports = { runTests };

