// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS handling
const morgan = require('morgan'); // Logging
const validator = require('validator'); // Input validation

const app = express();

// =====================================
// SECURITY MIDDLEWARE
// =====================================

// 1. Security Headers - helmet adds various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration - restrict origins in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  maxAge: 86400 // Cache preflight for 24 hours
};
app.use(cors(corsOptions));

// 3. Rate Limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too Many Requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: Math.ceil(req.rateLimit.resetTime / 1000)
    });
  }
});
app.use(limiter);

// 4. Request Body Parsing with Size Limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true    // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 5. Request Timeout
app.use((req, res, next) => {
  req.setTimeout(30000, () => {
    res.status(408).json({
      error: 'Request Timeout',
      message: 'Request took too long to process'
    });
  });
  next();
});

// 6. Logging (use 'combined' in production, 'dev' in development)
const logFormat = process.env.NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(logFormat));

// 7. Disable Express Information Disclosure
app.disable('x-powered-by');

// =====================================
// INPUT VALIDATION HELPERS
// =====================================

const validateUserId = (id) => {
  // Validate that ID is a positive integer
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1 || numId > Number.MAX_SAFE_INTEGER) {
    return { valid: false, error: 'Invalid user ID format' };
  }
  return { valid: true, value: numId };
};

const sanitizeQueryParams = (params) => {
  const sanitized = {};
  for (const [key, value] of Object.entries(params)) {
    // Only allow alphanumeric keys
    if (!/^[a-zA-Z0-9_]+$/.test(key)) {
      continue;
    }
    // Sanitize string values
    if (typeof value === 'string') {
      sanitized[key] = validator.escape(value).trim();
    }
  }
  return sanitized;
};

// =====================================
// ROUTES
// =====================================

// Health Check Endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Even health checks should handle errors
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

// Get All Users Endpoint with Pagination and Filtering
app.get('/users', (req, res, next) => {
  try {
    // Sanitize query parameters
    const sanitizedParams = sanitizeQueryParams(req.query);

    // Validate pagination parameters
    let page = 1;
    let limit = 10;

    if (sanitizedParams.page) {
      page = parseInt(sanitizedParams.page, 10);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Invalid page parameter'
        });
      }
    }

    if (sanitizedParams.limit) {
      limit = parseInt(sanitizedParams.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Invalid limit parameter (must be between 1 and 100)'
        });
      }
    }

    // Mock user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = allUsers.slice(startIndex, endIndex);

    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit)
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Get Single User by ID
app.get('/users/:id', (req, res, next) => {
  try {
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        error: 'Bad Request',
        message: validation.error
      });
    }

    const userId = validation.value;

    // Mock user data (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
