// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers - Helmet protects against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Body Parser with security options
app.use(express.json({ 
  limit: '10kb', // Limit payload size to prevent DoS
  strict: true   // Only parse arrays and objects
}));

app.use(express.urlencoded({ 
  extended: false, 
  limit: '10kb',
  parameterLimit: 100 // Limit number of parameters
}));

// 4. Request Logging (for security audit trail)
app.use(morgan('combined'));

// Disable x-powered-by header to avoid exposing Express
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Sanitize string input to prevent XSS
 * @param {string} input - User input to sanitize
 * @returns {string} Sanitized input
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Escape HTML entities
  return validator.escape(input.trim());
};

/**
 * Validate pagination parameters
 * @param {object} req - Express request object
 * @param {object} res - Express response object
 * @param {function} next - Next middleware
 */
const validatePagination = (req, res, next) => {
  const { page, limit } = req.query;

  if (page !== undefined) {
    if (!validator.isInt(String(page), { min: 1, max: 1000 })) {
      return res.status(400).json({ 
        error: 'Invalid page parameter. Must be an integer between 1 and 1000.' 
      });
    }
    req.query.page = parseInt(page, 10);
  }

  if (limit !== undefined) {
    if (!validator.isInt(String(limit), { min: 1, max: 100 })) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be an integer between 1 and 100.' 
      });
    }
    req.query.limit = parseInt(limit, 10);
  }

  next();
};

/**
 * Validate user ID parameter
 * @param {object} req - Express request object
 * @param {object} res - Express response object
 * @param {function} next - Next middleware
 */
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!validator.isInt(String(id), { min: 1 })) {
    return res.status(400).json({ 
      error: 'Invalid user ID. Must be a positive integer.' 
    });
  }

  req.params.id = parseInt(id, 10);
  next();
};

/**
 * Validate email parameter
 * @param {object} req - Express request object
 * @param {object} res - Express response object
 * @param {function} next - Next middleware
 */
const validateEmail = (req, res, next) => {
  const { email } = req.query;

  if (email !== undefined) {
    if (!validator.isEmail(email)) {
      return res.status(400).json({ 
        error: 'Invalid email format.' 
      });
    }
    req.query.email = sanitizeInput(email);
  }

  next();
};

// ============================================
// ERROR HANDLING UTILITIES
// ============================================

/**
 * Custom error class for application errors
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async error wrapper to catch promise rejections
 * @param {function} fn - Async route handler
 * @returns {function} Wrapped handler
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * @route GET /health
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Get all users with optional filtering and pagination
 * @route GET /users
 * @query {number} [page] - Page number (1-1000)
 * @query {number} [limit] - Items per page (1-100)
 * @query {string} [email] - Filter by email
 */
app.get('/users', validatePagination, validateEmail, asyncHandler(async (req, res) => {
  try {
    // Simulated user database
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // Apply email filter if provided
    const { email, page = 1, limit = 10 } = req.query;
    if (email) {
      users = users.filter(user => user.email.toLowerCase().includes(email.toLowerCase()));
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Remove sensitive fields before sending
    const sanitizedUsers = paginatedUsers.map(({ id, name, email }) => ({
      id,
      name,
      email
    }));

    res.json({
      success: true,
      data: sanitizedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    // Pass errors to error handler
    throw new AppError('Failed to retrieve users', 500);
  }
}));

/**
 * Get user by ID
 * @route GET /users/:id
 * @param {number} id - User ID
 */
app.get('/users/:id', validateUserId, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Simulated user database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    throw new AppError('User not found', 404);
  }

  // Remove sensitive fields
  const { role, ...safeUser } = user;

  res.json({
    success: true,
    data: safeUser
  });
}));

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Handle 404 - Route not found
 */
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.originalUrl
  });
});

/**
 * Global error handler
 * Should be the last middleware
 */
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Default error values
  const statusCode = err.statusCode || 500;
  const message = err.isOperational ? err.message : 'Internal server error';

  // Send error response
  res.status(statusCode).json({
    success: false,
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

/**
 * Handle graceful shutdown
 */
const gracefulShutdown = (server) => {
  return () => {
    console.log('Received shutdown signal, closing server gracefully...');
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };
};

// ============================================
// SERVER INITIALIZATION
// ============================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  const server = app.listen(PORT, () => {
    console.log(`Server running securely on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle shutdown signals
  process.on('SIGTERM', gracefulShutdown(server));
  process.on('SIGINT', gracefulShutdown(server));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    process.exit(1);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    process.exit(1);
  });
}

module.exports = app;

