// Enhanced Express Application with Security Best Practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const cors = require('cors'); // CORS configuration

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration - restrict to specific origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// Body parser with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb',
  parameterLimit: 100 // Limit number of parameters
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  // Skip rate limiting for specific IPs (e.g., health checks)
  skip: (req) => {
    const trustedIPs = process.env.TRUSTED_IPS?.split(',') || [];
    return trustedIPs.includes(req.ip);
  }
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.'
});

// Disable X-Powered-By header to not reveal technology stack
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Sanitize input to prevent XSS attacks
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return validator.escape(validator.trim(input));
  }
  return input;
};

// Middleware to sanitize all request inputs
const sanitizeRequestInputs = (req, res, next) => {
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitizeInput(req.body[key]);
    });
  }
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitizeInput(req.query[key]);
    });
  }
  if (req.params) {
    Object.keys(req.params).forEach(key => {
      req.params[key] = sanitizeInput(req.params[key]);
    });
  }
  next();
};

app.use(sanitizeRequestInputs);

// ============================================
// VALIDATION FUNCTIONS
// ============================================

const validateUserId = (id) => {
  if (!id) {
    return { valid: false, error: 'User ID is required' };
  }

  // Check if it's a valid integer
  if (!validator.isInt(String(id), { min: 1 })) {
    return { valid: false, error: 'Invalid user ID format' };
  }

  return { valid: true, value: parseInt(id, 10) };
};

const validateEmail = (email) => {
  if (!email) {
    return { valid: false, error: 'Email is required' };
  }

  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }

  // Additional check for email length
  if (email.length > 254) {
    return { valid: false, error: 'Email is too long' };
  }

  return { valid: true, value: email.toLowerCase() };
};

const validateName = (name) => {
  if (!name) {
    return { valid: false, error: 'Name is required' };
  }

  // Check length
  if (name.length < 2 || name.length > 100) {
    return { valid: false, error: 'Name must be between 2 and 100 characters' };
  }

  // Check for valid characters (letters, spaces, hyphens, apostrophes)
  if (!/^[a-zA-Z\s\-']+$/.test(name)) {
    return { valid: false, error: 'Name contains invalid characters' };
  }

  return { valid: true, value: name };
};

// ============================================
// AUTHENTICATION MIDDLEWARE (Example)
// ============================================

const authenticateRequest = (req, res, next) => {
  // Example authentication - implement with JWT or session
  const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ 
      success: false,
      error: 'Authentication required' 
    });
  }

  // Validate API key (example - use proper authentication in production)
  const validApiKeys = process.env.VALID_API_KEYS?.split(',') || [];

  if (!validApiKeys.includes(apiKey)) {
    return res.status(403).json({ 
      success: false,
      error: 'Invalid authentication credentials' 
    });
  }

  next();
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no authentication required)
app.get('/health', (req, res, next) => {
  try {
    res.status(200).json({ 
      success: true,
      data: {
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      }
    });
  } catch (error) {
    next(error);
  }
});

// Get all users (with authentication)
app.get('/users', authenticateRequest, (req, res, next) => {
  try {
    // In production, this would query a database with parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter sensitive data before sending
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Don't include sensitive fields like password, tokens, etc.
    }));

    res.status(200).json({
      success: true,
      data: sanitizedUsers,
      count: sanitizedUsers.length
    });
  } catch (error) {
    next(error);
  }
});

// Get user by ID (with validation)
app.get('/users/:id', authenticateRequest, (req, res, next) => {
  try {
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        success: false,
        error: validation.error
      });
    }

    const userId = validation.value;

    // In production, use parameterized database queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found'
      });
    }

    res.status(200).json({
      success: true,
      data: user
    });
  } catch (error) {
    next(error);
  }
});

// Create user (with validation)
app.post('/users', authenticateRequest, strictLimiter, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate name
    const nameValidation = validateName(name);
    if (!nameValidation.valid) {
      return res.status(400).json({
        success: false,
        error: nameValidation.error
      });
    }

    // Validate email
    const emailValidation = validateEmail(email);
    if (!emailValidation.valid) {
      return res.status(400).json({
        success: false,
        error: emailValidation.error
      });
    }

    // In production:
    // 1. Check if email already exists
    // 2. Hash password if provided
    // 3. Use parameterized queries
    // 4. Implement proper transaction handling

    const newUser = {
      id: Date.now(), // Use proper ID generation in production
      name: nameValidation.value,
      email: emailValidation.value
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });
  } catch (error) {
    next(error);
  }
});

// Update user (with validation)
app.put('/users/:id', authenticateRequest, strictLimiter, (req, res, next) => {
  try {
    const idValidation = validateUserId(req.params.id);

    if (!idValidation.valid) {
      return res.status(400).json({
        success: false,
        error: idValidation.error
      });
    }

    const { name, email } = req.body;
    const updates = {};

    // Validate and add fields to update
    if (name !== undefined) {
      const nameValidation = validateName(name);
      if (!nameValidation.valid) {
        return res.status(400).json({
          success: false,
          error: nameValidation.error
        });
      }
      updates.name = nameValidation.value;
    }

    if (email !== undefined) {
      const emailValidation = validateEmail(email);
      if (!emailValidation.valid) {
        return res.status(400).json({
          success: false,
          error: emailValidation.error
        });
      }
      updates.email = emailValidation.value;
    }

    if (Object.keys(updates).length === 0) {
      return res.status(400).json({
        success: false,
        error: 'No valid fields to update'
      });
    }

    // In production: use parameterized database update

    res.status(200).json({
      success: true,
      data: { id: idValidation.value, ...updates },
      message: 'User updated successfully'
    });
  } catch (error) {
    next(error);
  }
});

// Delete user
app.delete('/users/:id', authenticateRequest, strictLimiter, (req, res, next) => {
  try {
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        success: false,
        error: validation.error
      });
    }

    // In production: use parameterized database delete

    res.status(200).json({
      success: true,
      message: 'User deleted successfully'
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Route not found',
    path: req.path
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  // Log error (use proper logging in production)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      success: false,
      error: 'Validation error',
      details: isDevelopment ? err.message : undefined
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      success: false,
      error: 'Unauthorized access'
    });
  }

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      success: false,
      error: 'Invalid JSON payload'
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      success: false,
      error: 'Payload too large'
    });
  }

  // Generic error response
  res.status(err.status || 500).json({
    success: false,
    error: isDevelopment ? err.message : 'Internal server error',
    stack: isDevelopment ? err.stack : undefined
  });
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

