// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const morgan = require('morgan');
const cors = require('cors');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration - restrict to specific origins in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.'
});

// Body parsing with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging (use 'combined' in production)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Disable X-Powered-By header to hide Express
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Sanitize and validate query parameters
 */
const validateQueryParams = (allowedParams) => {
  return (req, res, next) => {
    try {
      // Check for unexpected query parameters
      const receivedParams = Object.keys(req.query);
      const invalidParams = receivedParams.filter(param => !allowedParams.includes(param));

      if (invalidParams.length > 0) {
        return res.status(400).json({
          error: 'Invalid query parameters',
          invalidParams: invalidParams
        });
      }

      // Sanitize all query parameters
      Object.keys(req.query).forEach(key => {
        if (typeof req.query[key] === 'string') {
          req.query[key] = validator.escape(req.query[key]);
        }
      });

      next();
    } catch (error) {
      next(error);
    }
  };
};

/**
 * Validate user ID parameter
 */
const validateUserId = (req, res, next) => {
  try {
    const id = req.params.id;

    if (!id) {
      return res.status(400).json({
        error: 'User ID is required'
      });
    }

    // Check if ID is a valid integer
    if (!validator.isInt(id, { min: 1 })) {
      return res.status(400).json({
        error: 'Invalid user ID format. Must be a positive integer.'
      });
    }

    // Convert to integer and attach to request
    req.params.id = parseInt(id, 10);
    next();
  } catch (error) {
    next(error);
  }
};

/**
 * Validate pagination parameters
 */
const validatePagination = (req, res, next) => {
  try {
    const { page, limit } = req.query;

    if (page && !validator.isInt(page, { min: 1, max: 1000 })) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be between 1 and 1000.'
      });
    }

    if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.'
      });
    }

    // Set defaults
    req.pagination = {
      page: page ? parseInt(page, 10) : 1,
      limit: limit ? parseInt(limit, 10) : 10
    };

    next();
  } catch (error) {
    next(error);
  }
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * @route GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

/**
 * Get all users (with pagination and filtering)
 * @route GET /users
 * @query {number} page - Page number (default: 1)
 * @query {number} limit - Items per page (default: 10, max: 100)
 */
app.get('/users', 
  validateQueryParams(['page', 'limit', 'search']),
  validatePagination,
  strictLimiter,
  (req, res, next) => {
    try {
      // Mock data - in production, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination
      const { page, limit } = req.pagination;
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      // Filter sensitive data before sending response
      const sanitizedUsers = paginatedUsers.map(user => ({
        id: user.id,
        name: user.name,
        // In production, consider if email should be exposed
        email: user.email
      }));

      res.status(200).json({
        success: true,
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * Get user by ID
 * @route GET /users/:id
 * @param {number} id - User ID
 */
app.get('/users/:id',
  validateUserId,
  strictLimiter,
  (req, res, next) => {
    try {
      const userId = req.params.id;

      // Mock data - in production, query from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `No user exists with ID ${userId}`
        });
      }

      // Sanitize response
      const sanitizedUser = {
        id: user.id,
        name: user.name,
        email: user.email
      };

      res.status(200).json({
        success: true,
        data: sanitizedUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 handler - must be after all routes
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    path: req.originalUrl
  });
});

/**
 * Global error handler
 * This should be the last middleware
 */
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging service in production)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An internal server error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: 'Server Error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Only start server if not in test environment
if (process.env.NODE_ENV !== 'test') {
  const server = app.listen(PORT, HOST, () => {
    console.log(`🚀 Server running on ${HOST}:${PORT}`);
    console.log(`📝 Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

