// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const validator = require('validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too Many Requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

app.use('/api/', limiter);

// 3. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Logging (use Winston or similar in production)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// 5. Disable x-powered-by header
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Validates and sanitizes user ID
 * @param {string} id - User ID to validate
 * @returns {Object} - {valid: boolean, value: number, error: string}
 */
const validateUserId = (id) => {
  if (!id) {
    return { valid: false, error: 'User ID is required' };
  }

  // Check if it's a valid integer
  if (!validator.isInt(String(id), { min: 1, max: 999999 })) {
    return { valid: false, error: 'Invalid user ID format' };
  }

  return { valid: true, value: parseInt(id, 10) };
};

/**
 * Validates query parameters
 * @param {Object} query - Query parameters object
 * @returns {Object} - {valid: boolean, params: Object, error: string}
 */
const validateQueryParams = (query) => {
  const validatedParams = {};

  // Example: validate 'limit' parameter
  if (query.limit !== undefined) {
    if (!validator.isInt(String(query.limit), { min: 1, max: 100 })) {
      return { valid: false, error: 'Invalid limit parameter' };
    }
    validatedParams.limit = parseInt(query.limit, 10);
  } else {
    validatedParams.limit = 10; // default
  }

  // Example: validate 'offset' parameter
  if (query.offset !== undefined) {
    if (!validator.isInt(String(query.offset), { min: 0 })) {
      return { valid: false, error: 'Invalid offset parameter' };
    }
    validatedParams.offset = parseInt(query.offset, 10);
  } else {
    validatedParams.offset = 0; // default
  }

  // Sanitize search query if present
  if (query.search !== undefined) {
    const search = String(query.search).trim();
    if (search.length > 100) {
      return { valid: false, error: 'Search query too long' };
    }
    // Escape HTML to prevent XSS
    validatedParams.search = validator.escape(search);
  }

  return { valid: true, params: validatedParams };
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Custom error class for operational errors
 */
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async error wrapper to catch promise rejections
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ============================================
// ROUTES WITH VALIDATION
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Get all users with pagination and filtering
app.get('/api/users', asyncHandler(async (req, res, next) => {
  // Validate query parameters
  const validation = validateQueryParams(req.query);

  if (!validation.valid) {
    return res.status(400).json({
      error: 'Validation Error',
      message: validation.error
    });
  }

  const { limit, offset, search } = validation.params;

  // Mock data - in production, this would come from a database
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
  ];

  // Apply search filter if provided
  if (search) {
    users = users.filter(user => 
      user.name.toLowerCase().includes(search.toLowerCase()) ||
      user.email.toLowerCase().includes(search.toLowerCase())
    );
  }

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
}));

// Get single user by ID
app.get('/api/users/:id', asyncHandler(async (req, res, next) => {
  // Validate user ID
  const validation = validateUserId(req.params.id);

  if (!validation.valid) {
    return res.status(400).json({
      error: 'Validation Error',
      message: validation.error
    });
  }

  const userId = validation.value;

  // Mock data - in production, this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({
      error: 'Not Found',
      message: 'User not found'
    });
  }

  res.json({ data: user });
}));

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler - must be after all other routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.originalUrl
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for monitoring (use proper logger in production)
  if (process.env.NODE_ENV !== 'production') {
    console.error('Error:', err);
  } else {
    // In production, log to external service (e.g., Sentry, CloudWatch)
    console.error({
      message: err.message,
      stack: err.stack,
      url: req.originalUrl,
      method: req.method,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
  }

  // Set default status code
  const statusCode = err.statusCode || 500;
  const isOperational = err.isOperational || false;

  // Don't leak error details in production
  const errorResponse = {
    error: statusCode === 500 ? 'Internal Server Error' : err.name || 'Error',
    message: isOperational ? err.message : 'An unexpected error occurred'
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handler
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

// Graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('👋 SIGTERM RECEIVED. Shutting down gracefully');
  server.close(() => {
    console.log('💥 Process terminated!');
  });
});

module.exports = app;

# Security Improvements for app.js

## Summary of Issues Found

### 🔴 Critical Issues
1. **No Input Validation** - Parameters, headers, and query strings are not validated
2. **No Rate Limiting** - Application vulnerable to DoS attacks
3. **Missing Security Headers** - No protection against common web vulnerabilities
4. **Poor Error Handling** - Could expose sensitive information in stack traces

### 🟡 High Priority Issues
5. **No Request Size Limits** - Vulnerable to large payload attacks
6. **Missing CORS Configuration** - No control over cross-origin requests
7. **No Logging** - Security events are not tracked
8. **No Sanitization** - Potential XSS vulnerabilities

### 🟢 Medium Priority Issues
9. **Exposed Server Details** - X-Powered-By header reveals Express
10. **No Graceful Shutdown** - Could lose connections during deployment

---

## Implemented Security Improvements

### 1. **Security Headers (Helmet)**
```javascript
app.use(helmet({...}));
```
**Benefits:**
- Sets Content-Security-Policy to prevent XSS attacks
- Enables HSTS to enforce HTTPS
- Sets X-Frame-Options to prevent clickjacking
- Disables X-Powered-By header
- Sets X-Content-Type-Options to prevent MIME sniffing

### 2. **Rate Limiting**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
```
**Benefits:**
- Prevents brute force attacks
- Mitigates DoS attacks
- Limits API abuse
- Custom error messages for better UX

### 3. **Input Validation**
```javascript
const validateUserId = (id) => {
  if (!validator.isInt(String(id), { min: 1, max: 999999 })) {
    return { valid: false, error: 'Invalid user ID format' };
  }
  return { valid: true, value: parseInt(id, 10) };
};
```
**Benefits:**
- Validates data types and ranges
- Prevents injection attacks (SQL, NoSQL, Command)
- Sanitizes user input to prevent XSS
- Whitelist approach for query parameters

### 4. **Request Size Limits**
```javascript
app.use(express.json({ limit: '10kb' }));
```
**Benefits:**
- Prevents large payload DoS attacks
- Reduces memory consumption
- Faster request processing

### 5. **Comprehensive Error Handling**
```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
  }
}

// Async wrapper
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};
```
**Benefits:**
- Prevents information leakage in production
- Centralized error handling
- Proper HTTP status codes
- Stack traces only in development

### 6. **Request Logging**
```javascript
app.use(morgan('combined'));
```
**Benefits:**
- Audit trail for security incidents
- Performance monitoring
- Compliance requirements
- Debugging assistance

### 7. **Graceful Shutdown**
```javascript
process.on('SIGTERM', () => {
  server.close(() => {
    console.log('Process terminated!');
  });
});
```
**Benefits:**
- Prevents dropped connections
- Clean resource cleanup
- Better deployment experience

### 8. **404 Handler**
```javascript
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});
```
**Benefits:**
- Consistent error responses
- No stack traces on invalid routes
- Better API experience

---

## Required Dependencies

Install these packages for the improved version:

```bash
npm install helmet express-rate-limit morgan validator
```

### Package Descriptions:
- **helmet** - Sets various HTTP headers for security
- **express-rate-limit** - Rate limiting middleware
- **morgan** - HTTP request logger
- **validator** - String validation and sanitization library

---

## Additional Security Recommendations

### 1. **Environment Variables**
Create a `.env` file for sensitive configuration:
```env
NODE_ENV=production
PORT=3000
DATABASE_URL=postgresql://...
JWT_SECRET=your-secret-key
API_KEY=your-api-key
```

Use `dotenv` package:
```javascript
require('dotenv').config();
```

### 2. **CORS Configuration**
Add CORS middleware if your API is consumed by web clients:
```javascript
const cors = require('cors');

app.use(cors({
  origin: ['https://yourdomain.com'],
  credentials: true,
  maxAge: 86400
}));
```

### 3. **Authentication & Authorization**
Implement JWT-based authentication:
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

app.get('/api/users', authenticateToken, (req, res) => {
  // Protected route
});
```

### 4. **Database Security**
- Use parameterized queries to prevent SQL injection
- Implement connection pooling with limits
- Use read-only database users where appropriate
- Encrypt sensitive data at rest

Example with parameterized query:
```javascript
// ❌ UNSAFE - vulnerable to SQL injection
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;

// ✅ SAFE - parameterized query
const query = 'SELECT * FROM users WHERE id = $1';
const values = [req.params.id];
```

### 5. **HTTPS Only**
Force HTTPS in production:
```javascript
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect('https://' + req.headers.host + req.url);
  }
  next();
});
```

### 6. **Security Monitoring**
Integrate security monitoring tools:
- **Sentry** - Error tracking
- **Snyk** - Vulnerability scanning
- **OWASP Dependency-Check** - Dependency vulnerabilities
- **AWS GuardDuty** / **Azure Security Center** - Cloud security

### 7. **Regular Updates**
```bash
# Check for vulnerabilities
npm audit

# Fix automatically where possible
npm audit fix

# Update dependencies
npm update

# Check for outdated packages
npm outdated
```

### 8. **Security Testing**
Add security tests to your test suite:
```javascript
describe('Security Tests', () => {
  it('should prevent SQL injection in user ID', async () => {
    const res = await request(app)
      .get('/api/users/1 OR 1=1')
      .expect(400);
    expect(res.body.error).toBe('Validation Error');
  });

  it('should sanitize XSS in search query', async () => {
    const res = await request(app)
      .get('/api/users?search=<script>alert("xss")</script>')
      .expect(200);
    expect(res.body.data).toBeDefined();
  });

  it('should enforce rate limits', async () => {
    // Make 101 requests
    for (let i = 0; i < 101; i++) {
      if (i === 100) {
        const res = await request(app)
          .get('/api/users')
          .expect(429);
      } else {
        await request(app).get('/api/users');
      }
    }
  });
});
```

### 9. **Content Security Policy**
Fine-tune CSP headers based on your needs:
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
    fontSrc: ["'self'", "https://fonts.gstatic.com"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'", "https://api.yourdomain.com"],
    frameSrc: ["'none'"],
    objectSrc: ["'none'"]
  }
}));
```

### 10. **API Documentation**
Document security requirements:
- Authentication methods
- Rate limits
- Input validation rules
- Error response formats
- Allowed origins (CORS)

