// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // npm install helmet
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const validator = require('validator'); // npm install validator
const morgan = require('morgan'); // npm install morgan

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. Body parsing with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 4. Logging
app.use(morgan('combined'));

// 5. Disable unnecessary headers
app.disable('x-powered-by');

// ====================
// INPUT VALIDATION
// ====================

// Validation middleware for user ID
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({ 
      error: 'User ID is required',
      code: 'INVALID_INPUT'
    });
  }

  // Validate ID is a positive integer
  if (!validator.isInt(id, { min: 1 })) {
    return res.status(400).json({ 
      error: 'Invalid user ID format. Must be a positive integer.',
      code: 'INVALID_INPUT'
    });
  }

  next();
};

// Validation middleware for query parameters
const validateQueryParams = (req, res, next) => {
  const { limit, offset, search } = req.query;

  // Validate limit
  if (limit && !validator.isInt(String(limit), { min: 1, max: 100 })) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be between 1 and 100.',
      code: 'INVALID_INPUT'
    });
  }

  // Validate offset
  if (offset && !validator.isInt(String(offset), { min: 0 })) {
    return res.status(400).json({ 
      error: 'Invalid offset parameter. Must be a non-negative integer.',
      code: 'INVALID_INPUT'
    });
  }

  // Sanitize search input
  if (search) {
    // Check for SQL injection patterns
    const sqlInjectionPattern = /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|EXEC|EXECUTE|UNION|DECLARE)\b)|(-{2})|(')|(\bOR\b\s*\d+\s*=\s*\d+)/gi;
    if (sqlInjectionPattern.test(search)) {
      return res.status(400).json({ 
        error: 'Invalid search parameter.',
        code: 'INVALID_INPUT'
      });
    }

    // Limit search string length
    if (search.length > 100) {
      return res.status(400).json({ 
        error: 'Search parameter too long. Maximum 100 characters.',
        code: 'INVALID_INPUT'
      });
    }
  }

  next();
};

// ====================
// ROUTES
// ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Log error but don't expose internal details
    console.error('Health check failed:', error);
    res.status(500).json({ 
      status: 'error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Get all users with validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Simulated user data (in production, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(
      parseInt(offset), 
      parseInt(offset) + parseInt(limit)
    );

    res.status(200).json({
      data: paginatedUsers,
      meta: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset)
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Failed to fetch users',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Get single user by ID
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const { id } = req.params;

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found',
        code: 'NOT_FOUND'
      });
    }

    res.status(200).json({ data: user });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ 
      error: 'Failed to fetch user',
      code: 'INTERNAL_ERROR'
    });
  }
});

// ====================
// ERROR HANDLING
// ====================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Resource not found',
    code: 'NOT_FOUND',
    path: req.originalUrl
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error with details (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    code: err.code || 'INTERNAL_ERROR',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ====================
// SERVER STARTUP
// ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit the process
  // process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Gracefully shutdown
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

