// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// =====================
// SECURITY MIDDLEWARE
// =====================

// Set security HTTP headers
app.use(helmet());

// Enable CORS with restrictions
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent HTTP Parameter Pollution
app.use(hpp());

// Logging for monitoring (use 'combined' in production)
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// =====================
// INPUT VALIDATION
// =====================

const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({
      status: 'error',
      message: 'User ID is required'
    });
  }

  // Validate that ID is a positive integer
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId < 1 || !Number.isInteger(userId)) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid user ID. Must be a positive integer.'
    });
  }

  req.validatedUserId = userId;
  next();
};

const validateQueryParams = (req, res, next) => {
  const { page, limit, search } = req.query;

  // Validate page parameter
  if (page !== undefined) {
    const pageNum = parseInt(page, 10);
    if (isNaN(pageNum) || pageNum < 1) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid page parameter. Must be a positive integer.'
      });
    }
    req.validatedPage = pageNum;
  } else {
    req.validatedPage = 1;
  }

  // Validate limit parameter
  if (limit !== undefined) {
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid limit parameter. Must be between 1 and 100.'
      });
    }
    req.validatedLimit = limitNum;
  } else {
    req.validatedLimit = 10;
  }

  // Validate search parameter (sanitize to prevent injection)
  if (search !== undefined) {
    if (typeof search !== 'string' || search.length > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid search parameter. Must be a string with max 100 characters.'
      });
    }
    req.validatedSearch = search.trim();
  }

  next();
};

// =====================
// ROUTES
// =====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Get all users with pagination and search
app.get('/api/users', validateQueryParams, async (req, res, next) => {
  try {
    // Simulated data - in production, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    let filteredUsers = [...allUsers];

    // Apply search filter if provided
    if (req.validatedSearch) {
      const searchLower = req.validatedSearch.toLowerCase();
      filteredUsers = filteredUsers.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const startIndex = (req.validatedPage - 1) * req.validatedLimit;
    const endIndex = startIndex + req.validatedLimit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Remove sensitive information before sending
    const sanitizedUsers = paginatedUsers.map(({ id, name, email }) => ({
      id,
      name,
      email
    }));

    res.status(200).json({
      status: 'success',
      results: sanitizedUsers.length,
      total: filteredUsers.length,
      page: req.validatedPage,
      totalPages: Math.ceil(filteredUsers.length / req.validatedLimit),
      data: sanitizedUsers
    });
  } catch (error) {
    next(error);
  }
});

// Get single user by ID
app.get('/api/users/:id', validateUserId, async (req, res, next) => {
  try {
    // Simulated data - in production, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === req.validatedUserId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found'
      });
    }

    // Remove sensitive fields
    const { role, ...sanitizedUser } = user;

    res.status(200).json({
      status: 'success',
      data: sanitizedUser
    });
  } catch (error) {
    next(error);
  }
});

// =====================
// ERROR HANDLING
// =====================

// Handle 404 - Route not found
app.use((req, res, next) => {
  res.status(404).json({
    status: 'error',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging service in production)
  console.error('Error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      message: 'Validation error',
      ...(isDevelopment && { details: err.message })
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      status: 'error',
      message: 'Unauthorized access'
    });
  }

  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      status: 'error',
      message: 'Invalid token'
    });
  }

  if (err.name === 'CastError') {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid data format'
    });
  }

  // Default error response
  res.status(err.statusCode || 500).json({
    status: 'error',
    message: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// =====================
// SERVER STARTUP
// =====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handler
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on ${HOST}:${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

