 * app.get('/public', publicRoute);
 * app.get('/protected', protectedRoute);
 * app.get('/admin', adminRoute);
 * app.get('/users/:id/profile', userDataRoute);
 * 
 * // Protect existing routes
 * app.get('/users', authenticateToken, requireRole('admin'), ...);
 * app.post('/users', authenticateToken, requireRole('admin'), ...);
 * app.get('/users/:id', authenticateToken, requireOwnership, ...);
 */

// ============================================
// EXPORTS
// ============================================

module.exports = {
  // Middleware
  authenticateToken,
  optionalAuth,
  requireRole,
  requireOwnership,

  // Route Handlers
  registerUser,
  loginUser,
  getCurrentUser,
  logoutUser,
  refreshToken,

  // Examples
  publicRoute,
  protectedRoute,
  adminRoute,
  userDataRoute
};

