// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Request logging
app.use(morgan('combined'));

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// 5. CORS configuration (adjust based on your needs)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', 'https://yourdomain.com'); // Change to your domain
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// 6. Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Sanitize string input
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return validator.escape(validator.trim(str));
};

/**
 * Validate pagination parameters
 */
const validatePagination = (req, res, next) => {
  const { page, limit } = req.query;

  if (page !== undefined) {
    if (!validator.isInt(page, { min: 1, max: 1000 })) {
      return res.status(400).json({ 
        error: 'Invalid page parameter',
        message: 'Page must be an integer between 1 and 1000'
      });
    }
    req.query.page = parseInt(page, 10);
  }

  if (limit !== undefined) {
    if (!validator.isInt(limit, { min: 1, max: 100 })) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter',
        message: 'Limit must be an integer between 1 and 100'
      });
    }
    req.query.limit = parseInt(limit, 10);
  }

  next();
};

/**
 * Validate user ID parameter
 */
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id || !validator.isInt(id, { min: 1 })) {
    return res.status(400).json({ 
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  req.params.id = parseInt(id, 10);
  next();
};

/**
 * Validate email parameter
 */
const validateEmail = (req, res, next) => {
  const { email } = req.query;

  if (email && !validator.isEmail(email)) {
    return res.status(400).json({ 
      error: 'Invalid email',
      message: 'Please provide a valid email address'
    });
  }

  if (email) {
    req.query.email = sanitizeString(email);
  }

  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * No authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Don't expose internal error details
    res.status(500).json({ 
      status: 'error',
      message: 'Health check failed'
    });
  }
});

/**
 * Get all users endpoint
 * TODO: Add authentication middleware
 * TODO: Replace with actual database queries
 */
app.get('/users', validatePagination, validateEmail, (req, res, next) => {
  try {
    // Mock data - replace with actual database query
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    // Filter by email if provided
    if (req.query.email) {
      users = users.filter(u => u.email === req.query.email);
    }

    // Apply pagination
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    // Don't expose sensitive data in response
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: sanitizeString(user.name),
      email: user.email, // Already validated
      // Don't expose role or other sensitive data without proper authorization
    }));

    res.status(200).json({
      data: sanitizedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

/**
 * Get user by ID endpoint
 * TODO: Add authentication middleware
 */
app.get('/users/:id', validateUserId, (req, res, next) => {
  try {
    const userId = req.params.id;

    // Mock data - replace with actual database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'User not found',
        message: `User with ID ${userId} does not exist`
      });
    }

    // Sanitize output
    const sanitizedUser = {
      id: user.id,
      name: sanitizeString(user.name),
      email: user.email,
    };

    res.status(200).json({ data: sanitizedUser });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 handler - must be after all routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    path: req.path
  });
});

/**
 * Global error handler - must be last
 */
app.use((err, req, res, next) => {
  // Log error for monitoring (use proper logging service in production)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Don't expose internal errors in production
  const message = statusCode === 500 && process.env.NODE_ENV === 'production'
    ? 'An internal server error occurred'
    : err.message || 'Something went wrong';

  res.status(statusCode).json({
    error: 'Error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Only start server if not imported as a module
if (require.main === module) {
  const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });

  process.on('SIGINT', () => {
    console.log('SIGINT signal received: closing HTTP server');
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  });
}

module.exports = app;

# Security Recommendations for app.js

## Overview
This document outlines security vulnerabilities found in the original app.js and provides recommendations for improvement.

---

## Critical Security Issues Found

### 1. **Missing Security Headers**
**Risk Level:** HIGH

**Issue:** No security headers are configured, leaving the application vulnerable to:
- Cross-Site Scripting (XSS)
- Clickjacking attacks
- MIME-sniffing attacks
- Man-in-the-middle attacks

**Solution:** 
- Implement Helmet.js middleware
- Configure Content Security Policy (CSP)
- Enable HTTP Strict Transport Security (HSTS)
- Set X-Frame-Options, X-Content-Type-Options

### 2. **No Input Validation**
**Risk Level:** HIGH

**Issue:** Query parameters and request data are not validated or sanitized
- SQL Injection risk (if database queries are added)
- NoSQL Injection risk
- Path traversal attacks
- Prototype pollution

**Solution:**
- Validate all inputs using validator.js or joi
- Sanitize user inputs
- Implement whitelist validation
- Use parameterized queries for database operations

### 3. **No Rate Limiting**
**Risk Level:** HIGH

**Issue:** Endpoints are vulnerable to:
- Denial of Service (DoS) attacks
- Brute force attacks
- API abuse

**Solution:**
- Implement express-rate-limit
- Configure different limits for different endpoints
- Consider using Redis for distributed rate limiting

### 4. **No Error Handling**
**Risk Level:** MEDIUM

**Issue:** Unhandled errors can:
- Crash the application
- Expose sensitive information (stack traces, file paths)
- Leak internal implementation details

**Solution:**
- Implement centralized error handling middleware
- Use try-catch blocks in async functions
- Log errors securely without exposing details to users
- Return generic error messages in production

### 5. **No Authentication/Authorization**
**Risk Level:** HIGH

**Issue:** The `/users` endpoint exposes user data without:
- Authentication verification
- Authorization checks
- Access control

**Solution:**
- Implement JWT or session-based authentication
- Add role-based access control (RBAC)
- Verify user permissions before returning sensitive data

### 6. **No CORS Configuration**
**Risk Level:** MEDIUM

**Issue:** Missing CORS policy can:
- Allow unauthorized cross-origin requests
- Enable CSRF attacks
- Expose API to unintended domains

**Solution:**
- Configure CORS with specific allowed origins
- Don't use wildcard (*) in production
- Implement CSRF tokens for state-changing operations

### 7. **Sensitive Data Exposure**
**Risk Level:** MEDIUM

**Issue:** User data returned without:
- Data minimization
- Field filtering
- Proper access control

**Solution:**
- Return only necessary fields
- Implement field-level permissions
- Sanitize output data
- Use DTO (Data Transfer Objects)

### 8. **No Request Size Limits**
**Risk Level:** MEDIUM

**Issue:** Without body parser limits:
- Payload size attacks possible
- Memory exhaustion attacks
- Server resource abuse

**Solution:**
- Set request body size limits (e.g., 10kb)
- Implement file upload size restrictions
- Monitor memory usage

### 9. **Information Disclosure**
**Risk Level:** MEDIUM

**Issue:** The X-Powered-By header reveals:
- Server technology (Express.js)
- Potential attack vectors
- Framework version information

**Solution:**
- Disable X-Powered-By header
- Remove version information from responses
- Use security through obscurity as additional layer

### 10. **No Logging/Monitoring**
**Risk Level:** MEDIUM

**Issue:** Without logging:
- Security incidents go undetected
- Difficult to debug issues
- No audit trail
- Cannot track abuse patterns

**Solution:**
- Implement request logging (morgan)
- Log security events
- Monitor for suspicious patterns
- Set up alerting for anomalies

---

## Required Dependencies

Install these packages to implement the security improvements:

```bash
npm install helmet express-rate-limit validator morgan
npm install --save-dev @types/express @types/validator
```

---

## Additional Security Best Practices

### 1. Environment Variables
```javascript
// Use environment variables for sensitive data
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  dbUrl: process.env.DATABASE_URL,
  jwtSecret: process.env.JWT_SECRET,
};

// Never commit .env files
```

### 2. Authentication Implementation
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Access token is required' 
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'Invalid or expired token' 
      });
    }
    req.user = user;
    next();
  });
};

// Apply to protected routes
app.get('/users', authenticateToken, (req, res) => {
  // Route handler
});
```

### 3. SQL Injection Prevention
```javascript
// BAD - Vulnerable to SQL injection
const userId = req.params.id;
const query = `SELECT * FROM users WHERE id = ${userId}`;

// GOOD - Using parameterized queries
const userId = req.params.id;
const query = 'SELECT * FROM users WHERE id = ?';
db.execute(query, [userId]);
```

### 4. XSS Prevention
```javascript
const validator = require('validator');

// Sanitize user input
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return validator.escape(validator.trim(input));
};

// Use Content Security Policy
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  }
}));
```

### 5. Secure Session Configuration
```javascript
const session = require('express-session');

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true, // HTTPS only
    httpOnly: true, // Prevent XSS
    maxAge: 3600000, // 1 hour
    sameSite: 'strict' // CSRF protection
  }
}));
```

### 6. Database Query Validation
```javascript
const validateDatabaseQuery = (req, res, next) => {
  const { sortBy, orderBy } = req.query;

  // Whitelist allowed sort fields
  const allowedSortFields = ['id', 'name', 'email', 'createdAt'];
  const allowedOrderValues = ['ASC', 'DESC'];

  if (sortBy && !allowedSortFields.includes(sortBy)) {
    return res.status(400).json({
      error: 'Invalid sort field',
      message: `Allowed fields: ${allowedSortFields.join(', ')}`
    });
  }

  if (orderBy && !allowedOrderValues.includes(orderBy.toUpperCase())) {
    return res.status(400).json({
      error: 'Invalid order value',
      message: 'Must be ASC or DESC'
    });
  }

  next();
};
```

### 7. File Upload Security
```javascript
const multer = require('multer');
const path = require('path');

const fileFilter = (req, file, cb) => {
  // Whitelist allowed extensions
  const allowedTypes = /jpeg|jpg|png|gif|pdf/;
  const extname = allowedTypes.test(
    path.extname(file.originalname).toLowerCase()
  );
  const mimetype = allowedTypes.test(file.mimetype);

  if (mimetype && extname) {
    return cb(null, true);
  } else {
    cb(new Error('Invalid file type'));
  }
};

const upload = multer({
  limits: { fileSize: 5 * 1024 * 1024 }, // 5MB limit
  fileFilter: fileFilter,
  storage: multer.diskStorage({
    destination: './uploads/',
    filename: (req, file, cb) => {
      // Generate unique filename
      const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
      cb(null, file.fieldname + '-' + uniqueSuffix);
    }
  })
});
```

### 8. API Response Consistency
```javascript
// Standard success response
const successResponse = (res, data, statusCode = 200) => {
  res.status(statusCode).json({
    success: true,
    data: data,
    timestamp: new Date().toISOString()
  });
};

// Standard error response
const errorResponse = (res, message, statusCode = 500) => {
  res.status(statusCode).json({
    success: false,
    error: {
      message: message,
      statusCode: statusCode
    },
    timestamp: new Date().toISOString()
  });
};
```

---

## Testing Security

### 1. Security Testing Tools
- **OWASP ZAP** - Automated security scanner
- **Burp Suite** - Manual penetration testing
- **npm audit** - Check for vulnerable dependencies
- **Snyk** - Continuous security monitoring

### 2. Run Security Audits
```bash
# Check for vulnerable dependencies
npm audit

# Fix vulnerabilities automatically
npm audit fix

# Check with Snyk
npx snyk test
```

### 3. Penetration Testing Checklist
- [ ] Test for SQL/NoSQL injection
- [ ] Test for XSS vulnerabilities
- [ ] Test rate limiting effectiveness
- [ ] Verify authentication/authorization
- [ ] Test CSRF protection
- [ ] Check for sensitive data exposure
- [ ] Test error handling
- [ ] Verify HTTPS enforcement
- [ ] Test session management
- [ ] Check file upload security

---

## Production Deployment Checklist

- [ ] Enable HTTPS/TLS
- [ ] Set NODE_ENV=production
- [ ] Use environment variables for secrets
- [ ] Enable all security headers
- [ ] Configure rate limiting
- [ ] Set up logging and monitoring
- [ ] Implement authentication
- [ ] Configure CORS properly
- [ ] Use a reverse proxy (nginx)
- [ ] Set up firewall rules
- [ ] Regular security updates
- [ ] Backup strategy in place
- [ ] Incident response plan

---

## Monitoring and Alerting

### Key Metrics to Monitor
1. Failed authentication attempts
2. Rate limit violations
3. Error rates (4xx, 5xx)
