// Authentication and Authorization Middleware Examples
// Add these to your app for complete security

const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt'); // npm install bcrypt

// ==============================================
// JWT AUTHENTICATION MIDDLEWARE
// ==============================================

/**
 * Verify JWT token from Authorization header
 * Usage: app.get('/protected', authenticateToken, (req, res) => {...})
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      message: 'No token provided' 
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded; // Attach user info to request
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ 
        error: 'Token expired',
        message: 'Please login again' 
      });
    }
    return res.status(403).json({ 
      error: 'Invalid token',
      message: 'Authentication failed' 
    });
  }
};

/**
 * Optional authentication - proceeds even without token
 * Usage: app.get('/public-or-private', optionalAuth, (req, res) => {...})
 */
const optionalAuth = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    req.user = null;
    return next();
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
  } catch (error) {
    req.user = null;
  }

  next();
};

// ==============================================
// ROLE-BASED ACCESS CONTROL (RBAC)
// ==============================================

/**
 * Check if user has required role
 * Usage: app.delete('/users/:id', authenticateToken, requireRole('admin'), ...)
 */
const requireRole = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Authentication required' 
      });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'Insufficient permissions' 
      });
    }

    next();
  };
};

/**
 * Check if user owns the resource
 * Usage: app.put('/users/:id', authenticateToken, requireOwnership('id'), ...)
 */
const requireOwnership = (paramName = 'id') => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Authentication required' 
      });
    }

    const resourceUserId = parseInt(req.params[paramName], 10);

    // Allow if user is admin or owns the resource
    if (req.user.role === 'admin' || req.user.id === resourceUserId) {
      return next();
    }

    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'You can only access your own resources' 
    });
  };
};

// ==============================================
// USER REGISTRATION & LOGIN
// ==============================================

/**
 * Register a new user
 * POST /auth/register
 * Body: { email, password, name }
 */
const registerUser = async (req, res, next) => {
  try {
    const { email, password, name } = req.body;

    // Validate input
    if (!email || !password || !name) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: 'Email, password, and name are required' 
      });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: 'Invalid email format' 
      });
    }

    // Validate password strength
    if (password.length < 8) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: 'Password must be at least 8 characters long' 
      });
    }

    // Check password complexity
    const hasUpperCase = /[A-Z]/.test(password);
    const hasLowerCase = /[a-z]/.test(password);
    const hasNumbers = /\d/.test(password);
    const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);

    if (!hasUpperCase || !hasLowerCase || !hasNumbers || !hasSpecialChar) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: 'Password must contain uppercase, lowercase, number, and special character' 
      });
    }

    // Check if user already exists (mock - replace with DB query)
    // const existingUser = await db.query('SELECT * FROM users WHERE email = $1', [email]);
    // if (existingUser.rows.length > 0) { ... }

    // Hash password
    const saltRounds = 12;
    const hashedPassword = await bcrypt.hash(password, saltRounds);

    // Save user to database (mock)
    const newUser = {
      id: Date.now(), // In production, this would be from DB
      email: email.toLowerCase(),
      name,
      password: hashedPassword,
      role: 'user',
      createdAt: new Date()
    };

    // Don't send password in response
    const { password: _, ...userWithoutPassword } = newUser;

    res.status(201).json({ 
      message: 'User registered successfully',
      user: userWithoutPassword 
    });

  } catch (error) {
    next(error);
  }
};

/**
 * Login user
 * POST /auth/login
 * Body: { email, password }
 */
const loginUser = async (req, res, next) => {
  try {
    const { email, password } = req.body;

    // Validate input
    if (!email || !password) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: 'Email and password are required' 
      });
    }

    // Find user in database (mock)
    // const result = await db.query('SELECT * FROM users WHERE email = $1', [email]);
    // const user = result.rows[0];

    // Mock user for example
    const user = {
      id: 1,
      email: 'user@example.com',
      password: await bcrypt.hash('Password123!', 12),
      role: 'user',
      name: 'Test User'
    };

    if (!user) {
      // Use same error message to prevent user enumeration
      return res.status(401).json({ 
        error: 'Authentication failed',
        message: 'Invalid credentials' 
      });
    }

    // Verify password
    const isPasswordValid = await bcrypt.compare(password, user.password);

    if (!isPasswordValid) {
      return res.status(401).json({ 
        error: 'Authentication failed',
        message: 'Invalid credentials' 
      });
    }

    // Generate JWT tokens
    const accessToken = jwt.sign(
      { 
        id: user.id, 
        email: user.email, 
        role: user.role 
      },
      process.env.JWT_SECRET,
      { expiresIn: '15m' } // Short-lived access token
    );

    const refreshToken = jwt.sign(
      { id: user.id },
      process.env.JWT_REFRESH_SECRET,
      { expiresIn: '7d' } // Long-lived refresh token
    );

    // Store refresh token in database (for revocation capability)
    // await db.query('INSERT INTO refresh_tokens (user_id, token) VALUES ($1, $2)', 
    //   [user.id, refreshToken]);

    // Set refresh token in httpOnly cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production', // HTTPS only in production
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    // Send response
    res.status(200).json({ 
      message: 'Login successful',
      accessToken,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role
      }
    });

  } catch (error) {
    next(error);
  }
};

/**
