 * POST /auth/refresh
 */
const refreshAccessToken = async (req, res, next) => {
  try {
    const refreshToken = req.cookies.refreshToken;

    if (!refreshToken) {
      return res.status(401).json({ 
        error: 'Authentication required',
        message: 'No refresh token provided' 
