/**
 * Validate database connectivity
 * Requires: npm install pg
 */
async function validateDatabase() {
  console.log('\n[Database Validation]');

  // IMPORTANT: Only use with YOUR real database credentials
  if (!process.env.DATABASE_URL || process.env.DATABASE_URL.includes('CANARY')) {
    console.log('⚠️  SKIPPED - Canary/test value detected');
    console.log('   Replace with real DATABASE_URL to test');
    return false;
  }

  try {
    const { Pool } = require('pg');
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: 5000, // 5 second timeout
    });

    // Simple connection test
    const client = await pool.connect();
    const result = await client.query('SELECT NOW()');
    client.release();
    await pool.end();

    console.log('✅ Database connection successful');
    console.log(`   Server time: ${result.rows[0].now}`);
    return true;

  } catch (error) {
    console.log('❌ Database connection failed');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

/**
