// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging
app.use(morgan('combined'));

// Rate limiting - prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for specific endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.',
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

const validateQueryParams = (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    if (req.query.id) {
      const id = parseInt(req.query.id, 10);
      if (!Number.isInteger(id) || id < 1) {
        return res.status(400).json({ 
          error: 'Invalid input',
          message: 'ID must be a positive integer' 
        });
      }
      req.query.id = id; // Use sanitized value
    }

    if (req.query.email) {
      if (!validator.isEmail(req.query.email)) {
        return res.status(400).json({ 
          error: 'Invalid input',
          message: 'Invalid email format' 
        });
      }
      // Normalize email
      req.query.email = validator.normalizeEmail(req.query.email);
    }

    // Prevent NoSQL injection and XSS in string parameters
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Escape HTML to prevent XSS
        req.query[key] = validator.escape(req.query[key]);
      }
    });

    next();
  } catch (error) {
    return res.status(400).json({ 
      error: 'Bad request',
      message: 'Invalid query parameters' 
    });
  }
};

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Log error but don't expose details
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Health check failed' 
    });
  }
});

app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Mock database - in production, this would query a real database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    if (req.query.id) {
      const user = users.find(u => u.id === parseInt(req.query.id, 10));
      if (!user) {
        return res.status(404).json({ 
          error: 'Not found',
          message: 'User not found' 
        });
      }
      return res.status(200).json(user);
    }

    // Filter by email if provided
    if (req.query.email) {
      const user = users.find(u => u.email === req.query.email);
      if (!user) {
        return res.status(404).json({ 
          error: 'Not found',
          message: 'User not found' 
        });
      }
      return res.status(200).json(user);
    }

    // Return all users
    res.status(200).json({
      count: users.length,
      data: users
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users' 
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: 'The requested resource was not found' 
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log the error for debugging
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: 'Internal server error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  server.close(() => {
    process.exit(1);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;

