// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers
app.use(helmet());

// Enable CORS with specific origin
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// HTTP request logging
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined'));
} else {
  app.use(morgan('dev'));
}

// Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Sanitize user data before sending to client
 * @param {Object} user - User object
 * @returns {Object} Sanitized user object
 */
const sanitizeUserData = (user) => {
  return {
    id: user.id,
    name: String(user.name).trim(),
    email: String(user.email).toLowerCase().trim()
  };
};

/**
 * Handle validation errors
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next middleware function
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(e => ({
        field: e.param,
        message: e.msg
      }))
    });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * @route GET /health
 * @returns {Object} 200 - Health status
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

/**
 * Get all users
 * @route GET /users
 * @returns {Array} 200 - List of users
 */
app.get('/users', (req, res) => {
  try {
    // In production, this would query a database with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize user data before sending
    const sanitizedUsers = users.map(sanitizeUserData);

    res.status(200).json({
      success: true,
      data: sanitizedUsers,
      count: sanitizedUsers.length
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      success: false,
      error: 'Failed to retrieve users' 
    });
  }
});

/**
 * Get user by ID
 * @route GET /users/:id
 * @param {number} id - User ID (must be positive integer)
 * @returns {Object} 200 - User object
 * @returns {Object} 400 - Validation error
 * @returns {Object} 404 - User not found
 */
app.get('/users/:id', 
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt()
  ],
  handleValidationErrors,
  (req, res) => {
    try {
      const userId = req.params.id;

      // Mock data - in production, query database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          success: false,
          error: 'User not found' 
        });
      }

      res.status(200).json({
        success: true,
        data: sanitizeUserData(user)
      });
    } catch (error) {
      console.error('Error fetching user:', error);
      res.status(500).json({ 
        success: false,
        error: 'Failed to retrieve user' 
      });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 handler for undefined routes
 */
app.use((req, res) => {
  res.status(404).json({ 
    success: false,
    error: 'Resource not found',
    path: req.path
  });
});

/**
 * Global error handler
 * Catches all errors and prevents stack trace leakage in production
 */
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine if we're in development mode
  const isDev = process.env.NODE_ENV === 'development';

  // Set status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response
  const errorResponse = {
    success: false,
    error: isDev ? err.message : 'Internal server error',
    ...(isDev && { 
      stack: err.stack,
      details: err.details 
    })
  };

  res.status(statusCode).json(errorResponse);
});

// ============================================
// SERVER STARTUP
// ============================================

/**
 * Start server with proper error handling
 */
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

