// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Security headers with helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// 3. Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true   // Only accept arrays and objects
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 4. Logging (use 'combined' in production, or integrate with proper logging service)
app.use(morgan('combined'));

// 5. Disable x-powered-by header (also done by helmet, but explicit is better)
app.disable('x-powered-by');

// ===== CORS CONFIGURATION =====
// Uncomment and configure based on your needs
/*
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
*/

// ===== VALIDATION MIDDLEWARE =====

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

/**
 * Sanitize output to prevent XSS
 */
const sanitizeOutput = (obj) => {
  if (typeof obj === 'string') {
    return obj.replace(/[<>]/g, '');
  }
  if (Array.isArray(obj)) {
    return obj.map(sanitizeOutput);
  }
  if (obj && typeof obj === 'object') {
    const sanitized = {};
    for (const [key, value] of Object.entries(obj)) {
      sanitized[key] = sanitizeOutput(value);
    }
    return sanitized;
  }
  return obj;
};

// ===== ROUTES =====

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      success: true,
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Even simple endpoints should have error handling
    next(error);
  }
});

/**
 * Get users endpoint with pagination and filtering
 */
app.get('/users', [
  // Input validation
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a positive integer between 1 and 1000')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search term must not exceed 100 characters')
    .matches(/^[a-zA-Z0-9\s\-_@.]+$/)
    .withMessage('Search term contains invalid characters'),
  handleValidationErrors
], (req, res, next) => {
  try {
    // Mock data - in production, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    // Apply search filter if provided
    let filteredUsers = users;
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Sanitize output before sending
    res.json({
      success: true,
      data: sanitizeOutput(paginatedUsers),
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Example POST endpoint with input validation
 */
app.post('/users', [
  // Comprehensive input validation
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Must be a valid email address')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email must not exceed 255 characters'),
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 })
    .withMessage('Age must be between 0 and 150')
    .toInt(),
  handleValidationErrors
], async (req, res, next) => {
  try {
    const { name, email, age } = req.body;

    // Additional business logic validation
    // In production: check if email already exists in database
    const existingUser = false; // Mock check

    if (existingUser) {
      return res.status(409).json({
        success: false,
        message: 'User with this email already exists'
      });
    }

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In production: use database-generated ID
      name: sanitizeOutput(name),
      email: sanitizeOutput(email),
      age: age || null,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Example GET by ID with parameter validation
 */
app.get('/users/:id', [
  // Validate URL parameters
  query('include')
    .optional()
    .isIn(['profile', 'posts', 'comments'])
    .withMessage('Invalid include parameter'),
  handleValidationErrors
], (req, res, next) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Validate ID is a positive integer
    if (!Number.isInteger(userId) || userId < 1) {
      return res.status(400).json({
        success: false,
        message: 'Invalid user ID'
      });
    }

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        message: 'User not found'
      });
    }

    res.json({
      success: true,
      data: sanitizeOutput(user)
    });
  } catch (error) {
    next(error);
  }
});

// ===== ERROR HANDLING =====

/**
 * 404 handler - must be after all routes
 */
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found',
    path: req.originalUrl
  });
});

/**
 * Global error handler - must be last middleware
 */
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors in production
  const statusCode = err.statusCode || err.status || 500;
  const message = statusCode === 500 && process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    success: false,
    message,
    ...(process.env.NODE_ENV === 'development' && { 
      stack: err.stack,
      error: err 
    })
  });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, you might want to restart the process
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to restart the process
  process.exit(1);
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The current `app.js` implementation is a basic Express application with **significant security vulnerabilities**. This review identifies critical issues and provides actionable recommendations.

---

## 🔴 Critical Security Vulnerabilities

### 1. **No Input Validation**
**Risk Level:** CRITICAL

**Current Issue:**
- No validation of query parameters, URL parameters, or request bodies
- Vulnerable to injection attacks, XSS, and malformed input

**Recommendation:**
```javascript
// Use express-validator for robust validation
const { query, body, param, validationResult } = require('express-validator');

app.get('/users/:id', [
  param('id').isInt().toInt(),
  query('search').optional().trim().escape()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Safe to use req.params.id and req.query.search
});
```

---

### 2. **Missing Security Headers**
**Risk Level:** CRITICAL

**Current Issue:**
- No protection against XSS, clickjacking, MIME sniffing
- Exposes server technology via `X-Powered-By` header

**Recommendation:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true
}));

app.disable('x-powered-by');
```

---

### 3. **No Error Handling Middleware**
**Risk Level:** HIGH

**Current Issue:**
- Unhandled errors may crash the application
- Stack traces may leak sensitive information
- No centralized error logging

**Recommendation:**
```javascript
// Catch-all error handler (must be last)
app.use((err, req, res, next) => {
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ message: 'Resource not found' });
});
```

---

### 4. **No Rate Limiting**
**Risk Level:** HIGH

**Current Issue:**
- Vulnerable to brute force attacks
- Vulnerable to DoS attacks
- No protection against API abuse

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Max 100 requests per IP
  message: 'Too many requests, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Stricter limits for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5
});

app.use('/login', strictLimiter);
app.use('/register', strictLimiter);
```

---

### 5. **No Request Size Limits**
**Risk Level:** HIGH

**Current Issue:**
- Vulnerable to large payload attacks
- Can cause memory exhaustion
- No protection against malformed JSON

**Recommendation:**
```javascript
app.use(express.json({ 
  limit: '10kb',
  strict: true  // Only accept arrays and objects
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb',
  parameterLimit: 100  // Limit number of parameters
}));
```

---

### 6. **Missing CORS Configuration**
**Risk Level:** MEDIUM

**Current Issue:**
- Default CORS behavior may be too permissive
- Cross-origin requests not controlled

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // Cache preflight requests for 24 hours
}));
```

---

### 7. **No Logging/Monitoring**
**Risk Level:** MEDIUM

**Current Issue:**
- No audit trail for requests
- Difficult to detect security incidents
- No metrics for monitoring

**Recommendation:**
```javascript
const morgan = require('morgan');

// Development
app.use(morgan('dev'));

// Production - log to file or service
const fs = require('fs');
const path = require('path');

const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'access.log'),
  { flags: 'a' }
);

app.use(morgan('combined', { stream: accessLogStream }));

// Consider integrating with:
// - Winston for structured logging
// - Sentry for error tracking
// - DataDog/New Relic for APM
```

---

### 8. **Hardcoded Sensitive Data**
