## 📋 Input Validation Examples

### Query Parameters
```javascript
const { query, validationResult } = require('express-validator');

app.get('/search', [
  query('q')
    .trim()
    .notEmpty().withMessage('Search query required')
    .isLength({ max: 100 }).withMessage('Query too long')
    .matches(/^[a-zA-Z0-9\s]+$/).withMessage('Invalid characters'),
  query('page')
    .optional()
    .isInt({ min: 1 }).withMessage('Invalid page')
    .toInt()
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Safe to use req.query.q and req.query.page
});
```

### Request Body
```javascript
const { body } = require('express-validator');

app.post('/users', [
  body('email')
    .trim()
    .isEmail().withMessage('Invalid email')
    .normalizeEmail(),
  body('password')
    .isLength({ min: 8 }).withMessage('Password too short')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain uppercase, lowercase, and number'),
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 }).withMessage('Invalid age')
    .toInt()
], async (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process validated data
});
```

### URL Parameters
