// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS handling
const morgan = require('morgan'); // Logging
const { body, query, validationResult } = require('express-validator'); // Input validation

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Enable CORS with restrictions
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Body parser with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true // Only accept arrays and objects
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 4. Rate limiting to prevent DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests, please try again later.'
});

// 5. Request logging (use 'combined' in production)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 6. Remove X-Powered-By header
app.disable('x-powered-by');

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      success: false,
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 * No sensitive data exposed
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      success: true,
      status: 'ok', 
      timestamp: new Date().toISOString(),
      // Don't expose internal details in production
      ...(process.env.NODE_ENV !== 'production' && { 
        version: process.env.APP_VERSION || '1.0.0' 
      })
    });
  } catch (error) {
    // Catch any unexpected errors
    res.status(500).json({ 
      success: false,
      error: 'Health check failed' 
    });
  }
});

/**
 * Get users endpoint with pagination and filtering
 * Input validation applied
 */
app.get('/users', [
  // Validate and sanitize query parameters
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a positive integer between 1 and 1000')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('search')
    .optional()
    .trim()
    .escape() // Prevent XSS
    .isLength({ max: 100 })
    .withMessage('Search term must be less than 100 characters'),
  handleValidationErrors
], async (req, res, next) => {
  try {
    // Extract validated parameters with defaults
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;
    const search = req.query.search || '';

    // Mock data - in production, fetch from database with parameterized queries
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter safely
    if (search) {
      users = users.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Return structured response
    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    // Pass errors to error handling middleware
    next(error);
  }
});

/**
 * Get single user by ID
 * Input validation applied
 */
app.get('/users/:id', [
  query('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
  handleValidationErrors
], async (req, res, next) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Validate ID is a number
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        success: false,
        error: 'Invalid user ID'
      });
    }

    // Mock data - use parameterized queries in production
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found'
      });
    }

    res.status(200).json({
      success: true,
      data: user
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * 404 handler - must be after all routes
 */
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: 'Resource not found',
    path: req.path
  });
});

/**
 * Global error handler
 * Prevents leaking sensitive information
 */
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging service in production)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send error response
  res.status(statusCode).json({
    success: false,
    error: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' // Generic message in production
      : err.message, // Detailed message in development
    ...(process.env.NODE_ENV !== 'production' && { 
      stack: err.stack 
    })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

/**
 * Graceful shutdown handler
 */
const gracefulShutdown = (server) => {
  console.log('Received shutdown signal, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown...');
    process.exit(1);
  }, 10000);
};

// Only start server if not in test environment
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  const HOST = process.env.HOST || '0.0.0.0';

  const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle graceful shutdown
  process.on('SIGTERM', () => gracefulShutdown(server));
  process.on('SIGINT', () => gracefulShutdown(server));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown(server);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown(server);
  });
}

module.exports = app;

// Security middleware helpers
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');

/**
 * Creates a rate limiter with custom configuration
 * @param {number} windowMs - Time window in milliseconds
 * @param {number} max - Maximum number of requests per window
 * @param {string} message - Custom error message
 */
const createRateLimiter = (windowMs = 15 * 60 * 1000, max = 100, message = 'Too many requests') => {
  return rateLimit({
    windowMs,
    max,
    message: { success: false, error: message },
    standardHeaders: true,
    legacyHeaders: false,
    handler: (req, res) => {
      res.status(429).json({
        success: false,
        error: message,
        retryAfter: Math.ceil(windowMs / 1000)
      });
    }
  });
};

/**
 * Validation error handler middleware
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Common validation rules
 */
const validationRules = {
  // ID validation
  id: param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt(),

  // Pagination validation
  page: query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be between 1 and 1000')
    .toInt(),

  limit: query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),

  // Search validation
  search: query('search')
    .optional()
    .trim()
    .escape()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search must be 1-100 characters'),

  // Email validation
  email: body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Valid email required'),

  // Password validation (strong password)
  password: body('password')
    .isLength({ min: 8, max: 128 })
    .withMessage('Password must be 8-128 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/)
    .withMessage('Password must contain uppercase, lowercase, number, and special character'),

  // Name validation
  name: body('name')
    .trim()
    .escape()
    .isLength({ min: 2, max: 50 })
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name must be 2-50 characters and contain only letters'),

  // Phone validation
  phone: body('phone')
    .optional()
    .matches(/^\+?[\d\s\-()]+$/)
    .isLength({ min: 10, max: 20 })
    .withMessage('Invalid phone number'),

  // URL validation
  url: body('url')
    .optional()
    .isURL({ protocols: ['http', 'https'], require_protocol: true })
    .withMessage('Invalid URL'),

  // Date validation
  date: body('date')
    .optional()
    .isISO8601()
    .toDate()
    .withMessage('Invalid date format (use ISO 8601)'),

  // Boolean validation
  boolean: query('active')
    .optional()
    .isBoolean()
    .toBoolean()
    .withMessage('Must be true or false'),

  // Array validation
  tags: body('tags')
    .optional()
    .isArray({ min: 0, max: 10 })
    .withMessage('Tags must be an array with max 10 items'),

  // Enum validation
  status: body('status')
    .optional()
    .isIn(['active', 'inactive', 'pending'])
    .withMessage('Status must be active, inactive, or pending')
};

/**
 * Sanitize output to prevent XSS
 * @param {Object} data - Data to sanitize
 * @returns {Object} Sanitized data
 */
const sanitizeOutput = (data) => {
  if (typeof data !== 'object' || data === null) {
    return data;
  }

  if (Array.isArray(data)) {
    return data.map(item => sanitizeOutput(item));
  }

  const sanitized = {};
  for (const [key, value] of Object.entries(data)) {
    if (typeof value === 'string') {
      // Remove potential XSS vectors
      sanitized[key] = value
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;')
        .replace(/\//g, '&#x2F;');
    } else if (typeof value === 'object') {
      sanitized[key] = sanitizeOutput(value);
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
};

/**
 * Async error wrapper to catch errors in async route handlers
 * @param {Function} fn - Async function to wrap
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Check if request is from allowed IP addresses
 * @param {Array} allowedIPs - Array of allowed IP addresses
 */
const ipWhitelist = (allowedIPs = []) => {
  return (req, res, next) => {
    const clientIP = req.ip || req.connection.remoteAddress;

    if (allowedIPs.length === 0 || allowedIPs.includes(clientIP)) {
      return next();
    }

    res.status(403).json({
      success: false,
      error: 'Access denied from your IP address'
    });
  };
};

/**
 * Require HTTPS in production
 */
const requireHTTPS = (req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure && req.get('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
};

/**
 * Add security response headers
 */
const securityHeaders = (req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS filter
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Feature policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  next();
};

/**
 * Log suspicious activity
 * @param {Object} req - Express request object
 * @param {string} reason - Reason for suspicious activity
 */
const logSuspiciousActivity = (req, reason) => {
  console.warn('SECURITY WARNING:', {
    timestamp: new Date().toISOString(),
    ip: req.ip,
    userAgent: req.get('user-agent'),
    path: req.path,
    method: req.method,
    reason,
    body: req.body,
    query: req.query
  });
};

/**
 * Detect and block common attack patterns
 */
const detectAttacks = (req, res, next) => {
  const suspiciousPatterns = [
    /(\%27)|(\')|(\-\-)|(\%23)|(#)/i,  // SQL injection
    /(\<script\>)|(\<\/script\>)/i,    // XSS
    /(\.\.\/)/i,                        // Path traversal
    /(\%00)/i,                          // Null byte
    /(\bexec\b|\beval\b|\bsystem\b)/i  // Command injection
  ];

  const checkString = JSON.stringify({
    ...req.query,
    ...req.params,
    ...req.body
  });

  for (const pattern of suspiciousPatterns) {
    if (pattern.test(checkString)) {
      logSuspiciousActivity(req, `Potential attack detected: ${pattern}`);
      return res.status(400).json({
        success: false,
        error: 'Invalid request detected'
      });
    }
  }

  next();
};

module.exports = {
  createRateLimiter,
  handleValidationErrors,
  validationRules,
  sanitizeOutput,
  asyncHandler,
  ipWhitelist,
  requireHTTPS,
  securityHeaders,
  logSuspiciousActivity,
  detectAttacks
};

