# Security Quick Reference Guide

## 🛡️ Essential Security Checklist

### 1. Input Validation
```javascript
// ✅ DO: Validate and sanitize all inputs
const { query, validationResult } = require('express-validator');

app.get('/users', [
  query('id').isInt().toInt(),
  query('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.query now
  }
]);

// ❌ DON'T: Use raw user input
app.get('/users', (req, res) => {
  const id = req.query.id; // UNSAFE!
  db.query(`SELECT * FROM users WHERE id = ${id}`); // SQL INJECTION!
});
```

### 2. Security Headers
```javascript
// ✅ DO: Use helmet for security headers
const helmet = require('helmet');
app.use(helmet());

// ❌ DON'T: Forget security headers
// This exposes you to XSS, clickjacking, and other attacks
```

### 3. Rate Limiting
```javascript
// ✅ DO: Implement rate limiting
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

// ❌ DON'T: Allow unlimited requests
// This opens you to DoS attacks
```

### 4. Error Handling
```javascript
// ✅ DO: Handle errors without leaking info
app.use((err, req, res, next) => {
  console.error(err.stack); // Log internally
  res.status(500).json({
    error: 'Internal server error' // Generic message
  });
});

// ❌ DON'T: Expose stack traces
app.use((err, req, res, next) => {
  res.status(500).json({
    error: err.message,
    stack: err.stack // INFORMATION DISCLOSURE!
  });
});
```

### 5. Authentication
```javascript
// ✅ DO: Protect sensitive routes
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

app.get('/admin', authenticateToken, (req, res) => {
  // Protected route
});

// ❌ DON'T: Leave sensitive endpoints unprotected
app.get('/admin', (req, res) => {
  // Anyone can access!
});
```

### 6. Database Queries
```javascript
// ✅ DO: Use parameterized queries
const userId = req.params.id;
db.query('SELECT * FROM users WHERE id = ?', [userId]);

// ✅ DO: Use ORM with proper escaping
User.findOne({ where: { id: userId } });

// ❌ DON'T: Use string concatenation
db.query(`SELECT * FROM users WHERE id = ${userId}`); // SQL INJECTION!
```

### 7. CORS Configuration
```javascript
// ✅ DO: Configure CORS properly
const cors = require('cors');
app.use(cors({
  origin: ['https://yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST']
}));

// ❌ DON'T: Allow all origins in production
app.use(cors()); // Allows ANY origin!
```

### 8. Environment Variables
```javascript
// ✅ DO: Use environment variables for secrets
require('dotenv').config();
const secret = process.env.JWT_SECRET;

// ❌ DON'T: Hardcode secrets
const secret = 'my-secret-key-123'; // EXPOSED IN CODE!
```

### 9. Request Size Limits
```javascript
// ✅ DO: Limit request payload size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ❌ DON'T: Accept unlimited payload sizes
// This allows memory exhaustion attacks
```

### 10. HTTPS Enforcement
```javascript
// ✅ DO: Enforce HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});

// ❌ DON'T: Allow HTTP in production
// This exposes data to man-in-the-middle attacks
```

